"""Unit tests for extras/kiln_autocolor.py with stand-ins for Klipper and
Kiln's IFS. Run from the repository root: python3 -m unittest discover tests
"""
import importlib.util
import os
import shutil
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
SPEC = importlib.util.spec_from_file_location(
    "kiln_autocolor", os.path.join(HERE, "..", "extras", "kiln_autocolor.py"))
ac = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(ac)

# The head and tail of a real OrcaSlicer 4-color file (T0, T1, T3 used)
ORCA = """; HEADER_BLOCK_START
; generated by OrcaSlicer
; filament: 2,4,1
; HEADER_BLOCK_END
PRINT_START BED=55 EXTRUDER=220 TOOL=0
T0
G1 X1
T1
T3
; CONFIG_BLOCK_START
; default_filament_colour = ;;;
; extruder_colour = #FF7F37;#BAB86C;#C7CDD7;#FFC0CB
; filament_colour = #FF7F37;#BAB86C;#C7CDD7;#FFC0CB
; filament_type = PLA;PLA;PLA;PLA
; CONFIG_BLOCK_END
; filament used [mm] = 2937.32, 942.41, 0.00, 932.24
; filament used [g] = 8.76, 2.81, 0.00, 2.78
"""

# AD5X-2's slots when that file was printed
SLOTS = {"1": {"type": "PLA", "color": "#BAB86C"},
         "2": {"type": "PLA", "color": "#FFC0CB"},
         "3": {"type": "PLA", "color": "#C7CDD7"},
         "4": {"type": "PLA+", "color": "#FF7F37"}}


def slots(*nums, info=SLOTS):
    return [{'slot': n, 'type': info[str(n)]['type'].upper(),
             'color': ac.parse_color(info[str(n)]['color'])} for n in nums]


class CommandError(Exception):
    pass


class FakeReactor:
    def monotonic(self):
        return 100.


class FakeGcode:
    def __init__(self, ifs):
        self.commands = {}
        self.scripts = []
        self.ifs = ifs
        self.printed = []
        self.commands["SDCARD_PRINT_FILE"] = self.orig_print_file

    def orig_print_file(self, gcmd):
        self.printed.append(gcmd.get('FILENAME'))

    def register_command(self, name, func, desc=None):
        if func is None:
            return self.commands.pop(name, None)
        assert name not in self.commands, name
        self.commands[name] = func

    def run_script_from_command(self, script):
        self.scripts.append(script)
        if script.startswith("IFS_MAP_TOOL"):
            p = dict(kv.split('=') for kv in script.split()[1:])
            self.ifs.tool_map[int(p['TOOL'])] = int(p['SLOT'])


class FakeGcmd:
    def __init__(self, **params):
        self.params = params
        self.messages = []

    def get(self, name, default=None):
        return self.params.get(name, default)

    def get_int(self, name, default=None, minval=None, maxval=None):
        v = self.params.get(name, default)
        return None if v is None else int(v)

    def respond_info(self, msg):
        self.messages.append(msg)

    def error(self, msg):
        return CommandError(msg)


class FakeIfs:
    def __init__(self, loaded=(1, 2, 3, 4)):
        self.loaded = list(loaded)
        self.connected = True
        self.tool_map = [1, 2, 3, 4]

    def get_status(self, eventtime):
        return {'connected': self.connected, 'loaded_channels': self.loaded,
                'tool_map': {str(t): self.tool_map[t] for t in range(4)}}


class FakeMaterials:
    def __init__(self, slots_info):
        self.slots_info = slots_info

    def get_status(self, eventtime):
        return {'slots': self.slots_info}


class FakeSdcard:
    def __init__(self, dirname):
        self.sdcard_dirname = dirname
        self.active = False

    def is_active(self):
        return self.active


class FakeSaveVariables:
    def __init__(self):
        self.allVariables = {}


class FakePrinter:
    command_error = CommandError

    def __init__(self, objects):
        self.objects = objects
        self.handlers = {}

    def get_reactor(self):
        return FakeReactor()

    def lookup_object(self, name, default=None):
        return self.objects.get(name, default)

    def register_event_handler(self, event, cb):
        self.handlers[event] = cb


class FakeConfig:
    def __init__(self, printer, **opts):
        self.printer = printer
        self.opts = opts

    def get_printer(self):
        return self.printer

    def getboolean(self, name, default):
        return self.opts.get(name, default)

    def getfloat(self, name, default, minval=None):
        return self.opts.get(name, default)


class ParseTest(unittest.TestCase):
    def test_orca_used_tools_from_header(self):
        info = ac.parse_gcode_info(ORCA)
        self.assertEqual(info['source'], "header")
        self.assertEqual([t['tool'] for t in info['tools']], [0, 1, 3])
        self.assertEqual(info['tools'][0]['color'], (0xFF, 0x7F, 0x37))
        self.assertEqual(info['tools'][2]['type'], "PLA")

    def test_filament_used_fallback(self):
        text = ORCA.replace("; filament: 2,4,1\n", "")
        info = ac.parse_gcode_info(text)
        self.assertEqual(info['source'], "filament used")
        self.assertEqual([t['tool'] for t in info['tools']], [0, 1, 3])

    def test_zmod_color_data(self):
        text = "; zmod_color_data = 0,2|#112233,#445566|PETG,PLA\n"
        info = ac.parse_gcode_info(text)
        self.assertEqual(info['source'], "zmod_color_data")
        self.assertEqual([(t['tool'], t['type']) for t in info['tools']],
                         [(0, "PETG"), (2, "PLA")])
        self.assertEqual(info['tools'][1]['color'], (0x44, 0x55, 0x66))

    def test_extruder_colour_when_no_filament_colour(self):
        text = ("; extruder_colour = #FF0000;#00FF00\n"
                "; filament_colour = ;\n; filament_type = PLA;PLA\n")
        info = ac.parse_gcode_info(text)
        self.assertEqual(info['tools'][1]['color'], (0, 255, 0))

    def test_family(self):
        self.assertEqual(ac.family("PLA+"), "PLA")
        self.assertEqual(ac.family("Silk PLA"), "PLA")
        self.assertEqual(ac.family("PETG-CF"), "PETG")
        self.assertEqual(ac.family("PET"), "PET")
        self.assertEqual(ac.family("PA6-CF"), "PA")

    def test_read_head_and_tail_of_big_file(self):
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d)
        head, rest = ORCA.split("; CONFIG_BLOCK_START")
        path = os.path.join(d, "big.gcode")
        with open(path, "w") as f:
            f.write(head + "G1 X1 Y1\n" * 200000
                    + "; CONFIG_BLOCK_START" + rest)
        info = ac.read_gcode_info(path)
        self.assertEqual([t['tool'] for t in info['tools']], [0, 1, 3])
        self.assertEqual(info['tools'][1]['color'], (0xBA, 0xB8, 0x6C))


class PlanTest(unittest.TestCase):
    def test_real_print(self):
        tools = ac.parse_gcode_info(ORCA)['tools']
        plan = ac.plan_map(tools, slots(1, 2, 3, 4))
        self.assertEqual(plan['map'], {0: 4, 1: 1, 3: 2})
        self.assertEqual(plan['problems'], [])
        self.assertIn("same family", plan['rows'][0]['notes'])

    def test_no_info_keeps_default(self):
        tools = [{'tool': t, 'color': None, 'type': None} for t in range(3)]
        plan = ac.plan_map(tools, slots(1, 2, 3, 4))
        self.assertEqual(plan['map'], {0: 1, 1: 2, 2: 3})

    def test_material_beats_color(self):
        info = {"1": {"type": "PETG", "color": "#FF0000"},
                "2": {"type": "PLA", "color": "#EE1111"}}
        tools = [{'tool': 0, 'color': (255, 0, 0), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(1, 2, info=info))
        self.assertEqual(plan['map'], {0: 2})

    def test_material_mismatch_reported(self):
        info = {"1": {"type": "PETG", "color": "#FF0000"}}
        tools = [{'tool': 0, 'color': (255, 0, 0), 'type': "ABS"}]
        plan = ac.plan_map(tools, slots(1, info=info))
        self.assertEqual(plan['map'], {0: 1})
        self.assertEqual(len(plan['problems']), 1)

    def test_distinct_slots_preferred(self):
        info = {"1": {"type": "PLA", "color": "#FFFFFF"},
                "2": {"type": "PLA", "color": "#F0F0F0"}}
        tools = [{'tool': 0, 'color': (255, 255, 255), 'type': "PLA"},
                 {'tool': 1, 'color': (250, 250, 250), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(1, 2, info=info))
        self.assertEqual(sorted(plan['map'].values()), [1, 2])

    def test_share_when_other_is_weak(self):
        info = {"1": {"type": "PLA", "color": "#FFFFFF"},
                "2": {"type": "PLA", "color": "#FF0000"}}
        tools = [{'tool': 0, 'color': (255, 255, 255), 'type': "PLA"},
                 {'tool': 1, 'color': (245, 245, 245), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(1, 2, info=info))
        self.assertEqual(plan['map'], {0: 1, 1: 1})
        self.assertIn("shares slot 1", plan['rows'][1]['notes'])

    def test_close_colors_keep_own_slots(self):
        # 4-color test print on AD5X-2: orange and red files, one orange
        # spool and a free pink one. Red goes to pink, not onto the orange.
        tools = [{'tool': 0, 'color': (0xFF, 0x80, 0x00), 'type': "PLA"},
                 {'tool': 3, 'color': (0xD2, 0x34, 0x22), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(2, 4))
        self.assertEqual(plan['map'], {0: 4, 3: 2})
        plan = ac.plan_map(tools, slots(2, 4), share_penalty=0)
        self.assertEqual(plan['map'], {0: 4, 3: 4})

    def test_perceptual_pairing(self):
        # calicat on AD5X-2: green and red files, olive, pink and silver
        # spools. RGB distance put red on olive; by eye green goes there.
        tools = [{'tool': 1, 'color': (0x00, 0xAE, 0x42), 'type': "PLA"},
                 {'tool': 3, 'color': (0xD2, 0x34, 0x22), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(1, 2, 3))
        self.assertEqual(plan['map'], {1: 1, 3: 2})

    def test_unloaded_slot_not_used(self):
        tools = [{'tool': 0, 'color': (0xBA, 0xB8, 0x6C), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(2, 3))
        self.assertIn(plan['map'][0], (2, 3))

    def test_tool_above_t3(self):
        tools = [{'tool': 4, 'color': (1, 2, 3), 'type': "PLA"}]
        plan = ac.plan_map(tools, slots(1))
        self.assertEqual(plan['map'], {})
        self.assertTrue(plan['problems'])


class PluginTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.dir)
        with open(os.path.join(self.dir, "cat.gcode"), "w") as f:
            f.write(ORCA)
        self.ifs = FakeIfs()
        self.gcode = FakeGcode(self.ifs)
        self.sd = FakeSdcard(self.dir)
        self.sv = FakeSaveVariables()
        self.printer = FakePrinter({
            'gcode': self.gcode, 'ifs': self.ifs, 'virtual_sdcard': self.sd,
            'ifs_materials': FakeMaterials(SLOTS), 'save_variables': self.sv})

    def make(self, **opts):
        plugin = ac.load_config(FakeConfig(self.printer, **opts))
        self.printer.handlers["klippy:connect"]()
        return plugin

    def start(self, name="cat.gcode"):
        gcmd = FakeGcmd(FILENAME=name)
        self.gcode.commands["SDCARD_PRINT_FILE"](gcmd)
        return gcmd

    def test_maps_then_prints(self):
        plugin = self.make()
        gcmd = self.start()
        self.assertEqual(self.gcode.printed, ["cat.gcode"])
        self.assertEqual(self.ifs.tool_map, [4, 1, 3, 2])
        self.assertIn("T0 PLA #FF7F37 -> slot 4", gcmd.messages[0])
        self.assertTrue(plugin.get_status(0)['last']['applied'])

    def test_manual_map_left_alone(self):
        self.make()
        self.ifs.tool_map = [2, 2, 3, 4]
        gcmd = self.start()
        self.assertEqual(self.ifs.tool_map, [2, 2, 3, 4])
        self.assertIn("already set", gcmd.messages[0])
        self.assertEqual(self.gcode.printed, ["cat.gcode"])

    def test_disabled_by_save_variable(self):
        self.sv.allVariables[ac.SAVE_VARIABLE] = 0
        self.make()
        self.start()
        self.assertEqual(self.ifs.tool_map, [1, 2, 3, 4])
        self.assertEqual(self.gcode.printed, ["cat.gcode"])

    def test_busy_sdcard_passes_through(self):
        self.make()
        self.sd.active = True
        self.start()
        self.assertEqual(self.gcode.scripts, [])

    def test_missing_file_still_prints(self):
        self.make()
        gcmd = self.start("nope.gcode")
        self.assertEqual(self.gcode.printed, ["nope.gcode"])
        self.assertIn("printing with the current tool map", gcmd.messages[0])

    def test_no_ifs_reading_still_prints(self):
        self.make()
        self.ifs.connected = False
        self.start()
        self.assertEqual(self.gcode.printed, ["cat.gcode"])
        self.assertEqual(self.ifs.tool_map, [1, 2, 3, 4])

    def test_stop_on_mismatch(self):
        self.make(stop_on_mismatch=True)
        with open(os.path.join(self.dir, "abs.gcode"), "w") as f:
            f.write("; filament_colour = #FF0000\n; filament_type = ABS\n")
        with self.assertRaises(CommandError):
            self.start("abs.gcode")
        self.assertEqual(self.gcode.printed, [])

    def test_autocolor_dry_run_and_apply(self):
        self.make()
        gcmd = FakeGcmd(FILENAME="cat.gcode")
        self.gcode.commands["AUTOCOLOR"](gcmd)
        self.assertEqual(self.ifs.tool_map, [1, 2, 3, 4])
        self.assertIn("-> slot 4", gcmd.messages[0])
        self.gcode.commands["AUTOCOLOR"](FakeGcmd(FILENAME="cat.gcode",
                                                  APPLY=1))
        self.assertEqual(self.ifs.tool_map, [4, 1, 3, 2])

    def test_enable_command_saves(self):
        plugin = self.make()
        self.gcode.commands["AUTOCOLOR_ENABLE"](FakeGcmd(ENABLE=0))
        self.assertFalse(plugin.enabled)
        self.assertIn("VARIABLE=autocolor_enabled VALUE=0",
                      self.gcode.scripts[-1])


if __name__ == "__main__":
    unittest.main()
